from datetime import datetime, date
import holidays

def total_business_days(date_ranges, country='US'):
    """
    Calculate the total number of business days across multiple date ranges,
    excluding weekends and the specified country's public holidays.

    Parameters:
    date_ranges (list): List of (start, end) tuples. Each date may be a
                        datetime, date, or parseable date string.
    country (str): ISO country code used to determine public holidays.

    Returns:
    int: Total count of business days across all ranges.
    """
    def _to_ts(d):
        if isinstance(d, datetime):
            return pd.Timestamp(d)
        if isinstance(d, date):
            return pd.Timestamp(d.year, d.month, d.day)
        return pd.Timestamp(d)

    total = 0
    for rng in date_ranges:
        if len(rng) != 2:
            raise ValueError("Each date range must be a (start, end) tuple.")
        start, end = _to_ts(rng[0]), _to_ts(rng[1])
        if start > end:
            raise ValueError("start date must not be after end date: {}".format(rng))
        years = list(range(start.year, end.year + 1))
        try:
            country_holidays = holidays.country_holidays(country, years=years)
        except (KeyError, NotImplementedError, AttributeError):
            raise ValueError("Invalid or unsupported country code: {}".format(country))
        hols = sorted(pd.Timestamp(h) for h in country_holidays.keys())
        bdays = pd.bdate_range(start=start, end=end, freq='C', holidays=hols)
        total += len(bdays)
    return total

